1495b7a5-691e-4ec6-88fa-06628f10e710	79	evolution_gen_79	import numpy as np\nimport re\nimport math\n\n# --- Helper Functions for Technical Indicators (Self-Improved with ADX) ---\n\ndef calculate_ema_series(data, period):\n    """Calculates a full series of Exponential Moving Averages."""\n    if len(data) < period:\n        return np.array([])\n    data_arr = np.array(data, dtype=float)\n    try:\n        import pandas as pd\n        return pd.Series(data_arr).ewm(span=period, adjust=False).mean().to_numpy()[period-1:]\n    except ImportError:\n        ema_values = np.zeros(len(data_arr) - period + 1, dtype=float)\n        ema_values[0] = np.mean(data_arr[:period])\n        multiplier = 2 / (period + 1)\n        for i in range(1, len(ema_values)):\n            ema_values[i] = (data_arr[i + period - 1] - ema_values[i-1]) * multiplier + ema_values[i-1]\n        return ema_values\n\ndef calculate_ema(prices, period):\n    """Calculates the Exponential Moving Average (EMA) for the latest price."""\n    if len(prices) < period:\n        return None\n    ema_s = calculate_ema_series(prices, period)\n    return ema_s[-1] if len(ema_s) > 0 else None\n\ndef calculate_rsi(prices, period=14):\n    """Calculates the Relative Strength Index (RSI) using Wilder's smoothing method."""\n    if len(prices) < period + 1:\n        return None\n    prices_arr = np.array(prices, dtype=float)\n    deltas = np.diff(prices_arr)\n    seed_gains = deltas[:period][deltas[:period] >= 0].sum()\n    seed_losses = -deltas[:period][deltas[:period] < 0].sum()\n    avg_gain = seed_gains / period\n    avg_loss = seed_losses / period\n    for i in range(period, len(deltas)):\n        delta = deltas[i]\n        gain = delta if delta >= 0 else 0.0\n        loss = -delta if delta < 0 else 0.0\n        avg_gain = (avg_gain * (period - 1) + gain) / period\n        avg_loss = (avg_loss * (period - 1) + loss) / period\n    if avg_loss == 0:\n        return 100.0\n    rs = avg_gain / avg_loss\n    return 100.0 - (100.0 / (1.0 + rs))\n\ndef calculate_macd_series(prices, short_period=12, long_period=26, signal_period=9):\n    """Calculates the MACD line, signal line, and histogram series."""\n    if len(prices) < long_period:\n        return None, None, None\n    short_ema_series = calculate_ema_series(prices, short_period)\n    long_ema_series = calculate_ema_series(prices, long_period)\n    macd_line = short_ema_series[len(short_ema_series)-len(long_ema_series):] - long_ema_series\n    if len(macd_line) < signal_period:\n        return macd_line, None, None\n    signal_line = calculate_ema_series(macd_line, signal_period)\n    histogram = macd_line[len(macd_line)-len(signal_line):] - signal_line\n    return macd_line, signal_line, histogram\n\ndef calculate_bollinger_bands(prices, period=20, num_std_dev=2):\n    """Calculates the Bollinger Bands for the latest price."""\n    if len(prices) < period:\n        return None, None, None\n    prices_slice = prices[-period:]\n    middle_band = np.mean(prices_slice)\n    std_dev = np.std(prices_slice)\n    upper_band = middle_band + (std_dev * num_std_dev)\n    lower_band = middle_band - (std_dev * num_std_dev)\n    return middle_band, upper_band, lower_band\n\ndef calculate_atr(prices, period=14):\n    """Calculates Average True Range (ATR) using close-to-close volatility."""\n    if len(prices) < period + 1:\n        return None\n    prices_arr = np.array(prices, dtype=float)\n    price_ranges = np.abs(np.diff(prices_arr))\n    atr_series = calculate_ema_series(price_ranges, period)\n    return atr_series[-1] if len(atr_series) > 0 else None\n\ndef calculate_adx(prices, period=14):\n    """\n    Calculates the Average Directional Index (ADX).\n    Since only close prices are available, TR is approximated by price change.\n    """\n    if len(prices) < 2 * period:\n        return None, None, None\n    \n    prices_arr = np.array(prices, dtype=float)\n    deltas = np.diff(prices_arr)\n    \n    tr = np.abs(deltas)\n    plus_dm = np.where((deltas > 0), deltas, 0)\n    minus_dm = np.where((deltas < 0), -deltas, 0)\n\n    # Wilder's smoothing (equivalent to EMA with alpha = 1/period)\n    def wilder_smooth(data, p):\n        smoothed = np.zeros_like(data)\n        smoothed[p-1] = np.sum(data[:p])\n        for i in range(p, len(data)):\n            smoothed[i] = smoothed[i-1] - (smoothed[i-1] / p) + data[i]\n        return smoothed\n\n    smooth_tr = wilder_smooth(tr, period)[period-1:]\n    smooth_plus_dm = wilder_smooth(plus_dm, period)[period-1:]\n    smooth_minus_dm = wilder_smooth(minus_dm, period)[period-1:]\n\n    with np.errstate(divide='ignore', invalid='ignore'):\n        plus_di = 100 * (smooth_plus_dm / smooth_tr)\n        minus_di = 100 * (smooth_minus_dm / smooth_tr)\n        plus_di[smooth_tr == 0] = 0\n        minus_di[smooth_tr == 0] = 0\n\n        dx_abs = np.abs(plus_di - minus_di)\n        dx_sum = plus_di + minus_di\n        dx = 100 * (dx_abs / dx_sum)\n        dx[dx_sum == 0] = 0\n    \n    if len(dx) < period:\n        return None, None, None\n        \n    adx = wilder_smooth(dx, period)[period-1:]\n    \n    return adx[-1], plus_di[-1], minus_di[-1]\n\ndef decide(current_price, price_history, news_context):\n    """\n    A self-improved, multi-regime trading strategy using ADX for robust\n    trend filtering and enhanced regime detection.\n\n    Parameters:\n        current_price (float): The current day's closing price for SPY.\n        price_history (list of float): List of historical closing prices up to yesterday.\n        news_context (str): Combined news headlines from the last 24 hours.\n\n    Returns:\n        str: "BUY", "SELL", or "HOLD"\n    """\n    # --- 1. Sentiment Analysis (Refined Keywords) ---\n    context_lower = news_context.lower()\n    sentiment_keywords = {\n        # Strong Positive\n        "fed pivot": 3.0, "rate cut": 2.5, "quantitative easing": 2.5, "soft landing": 2.5,\n        "cooling inflation": 2.5, "cpi miss": 2.5, "ai boom": 2.5, "