.0\n    for keyword, weight in sentiment_keywords.items():\n        pattern = r'\\b' + re.escape(keyword) + r'\\b'\n        for match in re.finditer(pattern, context_lower):\n            pre_context = context_lower[max(0, match.start() - 30):match.start()]\n            is_negated = any(neg_word in pre_context for neg_word in negation_words)\n            net_sentiment_score += -weight if is_negated else weight\n\n    # --- 2. Technical Indicators & Adaptive Regime Detection ---\n    all_prices = price_history + [current_price]\n    \n    SHORT_EMA_PERIOD = 12\n    LONG_EMA_PERIOD = 26\n    RSI_PERIOD = 14\n    BB_PERIOD = 20\n    DONCHIAN_PERIOD = 20\n    ADX_PERIOD = 14 # **NEW**\n    ATR_REGIME_SHORT = 10\n    ATR_REGIME_LONG = 50\n\n    required_history_length = max(LONG_EMA_PERIOD + 9, ATR_REGIME_LONG + 1, 2 * ADX_PERIOD)\n    if len(all_prices) < required_history_length:\n        return "HOLD"\n\n    # Calculate core indicators\n    short_ema = calculate_ema(all_prices, SHORT_EMA_PERIOD)\n    long_ema = calculate_ema(all_prices, LONG_EMA_PERIOD)\n    rsi = calculate_rsi(all_prices, RSI_PERIOD)\n    middle_band, upper_band, lower_band = calculate_bollinger_bands(all_prices, BB_PERIOD)\n    _, _, macd_hist_series = calculate_macd_series(all_prices)\n    short_atr = calculate_atr(all_prices, ATR_REGIME_SHORT)\n    long_atr = calculate_atr(all_prices, ATR_REGIME_LONG)\n    adx, plus_di, minus_di = calculate_adx(all_prices, ADX_PERIOD) # **NEW**\n\n    if any(v is None for v in [short_ema, long_ema, rsi, middle_band, short_atr, long_atr, adx]) or macd_hist_series is None or len(macd_hist_series) < 3:\n        return "HOLD"\n    \n    macd_histogram = macd_hist_series[-1]\n    prev_macd_histogram = macd_hist_series[-2]\n\n    # Regime Detection using ADX for trend strength\n    is_high_volatility = short_atr > (long_atr * 1.6)\n    is_trending_market = adx > 25\n    is_ranging_market = adx < 20\n\n    # --- 3. Multi-Regime Decision Logic ---\n    bullish_trend_structure = short_ema > long_ema and plus_di > minus_di\n    bearish_trend_structure = short_ema < long_ema and minus_di > plus_di\n\n    # **IMPROVEMENT**: Dynamic exit logic acting as a stateless trailing stop\n    if bullish_trend_structure and current_price < middle_band:\n        return "SELL" # Exit long position if trend structure breaks\n    if bearish_trend_structure and current_price > middle_band:\n        return "BUY" # Exit short position (by buying) if trend structure breaks\n\n    if is_high_volatility:\n        # === CRISIS MODE: High-conviction, sentiment-driven trend-following ===\n        BULLISH_SENTIMENT_THRESHOLD = 3.5\n        BEARISH_SENTIMENT_THRESHOLD = -3.5\n        if net_sentiment_score >= BULLISH_SENTIMENT_THRESHOLD and bullish_trend_structure and macd_histogram > 0 and rsi < 80:\n            return "BUY"\n        elif net_sentiment_score <= BEARISH_SENTIMENT_THRESHOLD and bearish_trend_structure and macd_histogram < 0 and rsi > 20:\n            return "SELL"\n    else:\n        # === NORMAL MODE: ADX-Filtered Logic ===\n        if is_trending_market:\n            # Sub-Regime: Confirmed Trending Market\n            if bullish_trend_structure and macd_histogram > 0 and prev_macd_histogram <= macd_histogram and rsi < 75 and net_sentiment_score > -2.5:\n                return "BUY"\n            \n            if bearish_trend_structure and macd_histogram < 0 and prev_macd_histogram >= macd_histogram and rsi > 25 and net_sentiment_score < 2.5:\n                return "SELL"\n        \n        elif is_ranging_market:\n            # Sub-Regime: Confirmed Ranging Market (Mean-Reversion Logic)\n            is_reversing_up = macd_histogram > prev_macd_histogram\n            if rsi < 32 and current_price < lower_band and net_sentiment_score > -3.5 and is_reversing_up:\n                return "BUY"\n                \n            is_reversing_down = macd_histogram < prev_macd_histogram\n            if rsi > 68 and current_price > upper_band and net_sentim