n        return 1.0\n    return std_dev_changes / avg_abs_change\n\ndef calculate_roc(prices, period=10):\n    """Calculates the Rate of Change (ROC) to measure momentum velocity."""\n    if len(prices) < period + 1:\n        return None\n    if prices[-1 - period] == 0:\n        return 0.0\n    return ((prices[-1] - prices[-1 - period]) / prices[-1 - period]) * 100\n\ndef calculate_donchian_channels(prices, period=20):\n    """Calculates the Donchian Channels for the latest price."""\n    if len(prices) < period:\n        return None, None\n    prices_slice = prices[-period:]\n    upper_channel = np.max(prices_slice)\n    lower_channel = np.min(prices_slice)\n    return upper_channel, lower_channel\n\ndef calculate_wma_series(data, period):\n    """Calculates a full series of Weighted Moving Averages."""\n    if len(data) < period:\n        return np.array([])\n    weights = np.arange(1, period + 1)\n    wma_values = np.zeros(len(data) - period + 1)\n    for i in range(len(wma_values)):\n        wma_values[i] = np.dot(data[i:i+period], weights) / weights.sum()\n    return wma_values\n\ndef calculate_coppock_curve(prices, roc1_period=14, roc2_period=11, wma_period=10):\n    """Calculates the Coppock Curve series, a long-term momentum indicator."""\n    if len(prices) < max(roc1_period, roc2_period) + wma_period:\n        return None\n    prices_arr = np.array(prices, dtype=float)\n    roc1 = ((prices_arr[roc1_period:] - prices_arr[:-roc1_period]) / prices_arr[:-roc1_period]) * 100\n    roc2 = ((prices_arr[roc2_period:] - prices_arr[:-roc2_period]) / prices_arr[:-roc2_period]) * 100\n    # Align the two ROC series\n    roc_sum = roc1[len(roc1)-len(roc2):] + roc2\n    if len(roc_sum) < wma_period:\n        return None\n    return calculate_wma_series(roc_sum, wma_period)\n\ndef decide(current_price, price_history, news_context):\n    """\n    Self-Improved Strategy v2: Integrates the Coppock Curve for long-term momentum\n    confirmation and a stateless volatility-based "panic sell" for risk management.\n    """\n    # --- 1. Sentiment Analysis (Capped Influence) ---\n    context_lower = news_context.lower()\n    sentiment_keywords = {\n        "fed pivot": 3.0, "rate cut": 2.5, "soft landing": 2.5, "cooling inflation": 2.5,\n        "ai boom": 2.5, "breakthrough": 2.0, "stimulus": 2.0, "dovish": 2.0, "bullish": 2.0,\n        "strong earnings": 2.0, "market rally": 2.0, "beat estimates": 1.5, "growth": 1.5,\n        "weak jobs report": 1.5, "fiscal stimulus": 2.0,\n        "recession": -3.0, "crisis": -3.0, "stagflation": -3.0, "hot inflation": -3.0,\n        "war": -3.0, "yield curve inversion": -3.5, "rate hike": -2.5, "hard landing": -2.5,\n        "geopolitical risk": -2.5, "cpi beat": -2.5, "vix spike": -2.5, "hawkish": -2.0,\n        "bearish": -2.0, "sell-off": -2.0, "bubble": -2.0, "uncertainty": -1.5,\n        "strong jobs report": -1.5, "supply chain disruption": -2.0, "debt ceiling": -2.0\n    }\n    negation_words = ["not", "no", "lack of", "fail to", "without", "struggle to", "avoids", "prevent"]\n    net_sentiment_score = 0.0\n    keyword_counts = {}\n    for keyword, weight in sentiment_keywords.items():\n        pattern = r'\\b' + re.escape(keyword) + r'\\b'\n        for match in re.finditer(pattern, context_lower):\n            pre_context = context_lower[max(0, match.start() - 30):match.start()]\n            is_negated = any(neg_word in pre_context for neg_word in negation_words)\n            \n            # **IMPROVEMENT**: Cap influence of a single keyword\n            keyword_counts[keyword] = keyword_counts.get(keyword, 0) + 1\n            if keyword_counts[keyword] > 2:\n                continue # Ignore more than 2 mentions of the same keyword\n            \n            net_sentiment_score += -weight if is_negated else weight\n\n    # --- 2. Technical Indicators & Adaptive Regime Detection ---\n    all_prices = price_history + [current_price]\n    \n    SHORT_EMA_PERIOD = 12\n    LONG_EMA_PERIOD = 26\n   